import React, { useState } from 'react';
import './CalculatorWidget.css';

const CalculatorWidget = ({ onClose }) => {
  const [display, setDisplay] = useState('0');
  const [previousValue, setPreviousValue] = useState(null);
  const [operation, setOperation] = useState(null);
  const [waitingForOperand, setWaitingForOperand] = useState(false);
  const [angleMode, setAngleMode] = useState('deg');
  const [tab, setTab] = useState('main');

  const inputDigit = (digit) => {
    if (waitingForOperand) {
      setDisplay(String(digit));
      setWaitingForOperand(false);
    } else {
      setDisplay(display === '0' ? String(digit) : display + digit);
    }
  };

  const inputDecimal = () => {
    if (waitingForOperand) {
      setDisplay('0.');
      setWaitingForOperand(false);
    } else if (display.indexOf('.') === -1) {
      setDisplay(display + '.');
    }
  };

  const clear = () => {
    setDisplay('0');
    setPreviousValue(null);
    setOperation(null);
    setWaitingForOperand(false);
  };

  const performOperation = (nextOperation) => {
    const inputValue = parseFloat(display);

    if (previousValue === null) {
      setPreviousValue(inputValue);
    } else if (operation) {
      const result = calculate(previousValue, inputValue, operation);
      setDisplay(String(result));
      setPreviousValue(result);
    }

    setWaitingForOperand(true);
    setOperation(nextOperation);
  };

  const calculate = (prev, current, op) => {
    switch (op) {
      case '+': return prev + current;
      case '-': return prev - current;
      case '*': return prev * current;
      case '/': return current !== 0 ? prev / current : 0;
      case '%': return prev % current;
      case '^': return Math.pow(prev, current);
      default: return current;
    }
  };

  const equals = () => {
    const inputValue = parseFloat(display);
    if (previousValue !== null && operation) {
      const result = calculate(previousValue, inputValue, operation);
      setDisplay(String(result));
      setPreviousValue(null);
      setOperation(null);
      setWaitingForOperand(true);
    }
  };

  const scientificFunc = (func) => {
    const value = parseFloat(display);
    let result;

    switch (func) {
      case 'sin': 
        result = angleMode === 'deg' ? Math.sin(value * Math.PI / 180) : Math.sin(value);
        break;
      case 'cos':
        result = angleMode === 'deg' ? Math.cos(value * Math.PI / 180) : Math.cos(value);
        break;
      case 'tan':
        result = angleMode === 'deg' ? Math.tan(value * Math.PI / 180) : Math.tan(value);
        break;
      case 'sqrt':
        result = Math.sqrt(value);
        break;
      case 'log':
        result = Math.log10(value);
        break;
      case 'ln':
        result = Math.log(value);
        break;
      case 'e':
        result = Math.E;
        break;
      case 'pi':
        result = Math.PI;
        break;
      case 'fact':
        result = factorial(value);
        break;
      default:
        result = value;
    }

    setDisplay(String(result));
    setWaitingForOperand(true);
  };

  const factorial = (n) => {
    if (n < 0) return NaN;
    if (n === 0 || n === 1) return 1;
    return n * factorial(n - 1);
  };

  const backspace = () => {
    if (display.length > 1) {
      setDisplay(display.slice(0, -1));
    } else {
      setDisplay('0');
    }
  };

  const toggleSign = () => {
    const value = parseFloat(display);
    setDisplay(String(-value));
  };

  return (
    <div className="calculator-widget">
      <div className="calculator-header">
        <div className="calculator-logo">
          <i className="fas fa-calculator"></i>
        </div>
        <div>
          <h3 className="calculator-title">Calculator</h3>
          <p className="calculator-brand">Scientific</p>
        </div>
      </div>

      <div className="calculator-content">
        <div className="calculator-screen-area">
          <div className="calculator-input">{display}</div>
        </div>

        <div className="controls-section">
          <div className="calculator-tabs">
            <button 
              className={`tab-button ${tab === 'main' ? 'active' : ''}`}
              onClick={() => setTab('main')}
            >
              Basic
            </button>
            <button 
              className={`tab-button ${tab === 'scientific' ? 'active' : ''}`}
              onClick={() => setTab('scientific')}
            >
              Scientific
            </button>
          </div>

          {tab === 'scientific' && (
            <div className="angle-mode">
              <button 
                className={`angle-button ${angleMode === 'deg' ? 'active' : ''}`}
                onClick={() => setAngleMode('deg')}
              >
                DEG
              </button>
              <button 
                className={`angle-button ${angleMode === 'rad' ? 'active' : ''}`}
                onClick={() => setAngleMode('rad')}
              >
                RAD
              </button>
            </div>
          )}
        </div>

        <div className="button-section">
          <div className="calculator-buttons">
            {tab === 'main' ? (
              <>
                <button className="calc-btn clear" onClick={clear}>C</button>
                <button className="calc-btn" onClick={backspace}><i className="fas fa-backspace"></i></button>
                <button className="calc-btn operator" onClick={() => performOperation('/')}>/</button>
                <button className="calc-btn operator" onClick={() => performOperation('*')}>×</button>

                <button className="calc-btn" onClick={() => inputDigit(7)}>7</button>
                <button className="calc-btn" onClick={() => inputDigit(8)}>8</button>
                <button className="calc-btn" onClick={() => inputDigit(9)}>9</button>
                <button className="calc-btn operator" onClick={() => performOperation('-')}>−</button>

                <button className="calc-btn" onClick={() => inputDigit(4)}>4</button>
                <button className="calc-btn" onClick={() => inputDigit(5)}>5</button>
                <button className="calc-btn" onClick={() => inputDigit(6)}>6</button>
                <button className="calc-btn operator" onClick={() => performOperation('+')}>+</button>

                <button className="calc-btn" onClick={() => inputDigit(1)}>1</button>
                <button className="calc-btn" onClick={() => inputDigit(2)}>2</button>
                <button className="calc-btn" onClick={() => inputDigit(3)}>3</button>
                <button className="calc-btn equals" onClick={equals}>=</button>

                <button className="calc-btn zero" onClick={() => inputDigit(0)}>0</button>
                <button className="calc-btn" onClick={inputDecimal}>.</button>
                <button className="calc-btn operator" onClick={() => performOperation('%')}>%</button>
              </>
            ) : (
              <>
                <button className="calc-btn clear" onClick={clear}>C</button>
                <button className="calc-btn scientific" onClick={() => scientificFunc('sin')}>sin</button>
                <button className="calc-btn scientific" onClick={() => scientificFunc('cos')}>cos</button>
                <button className="calc-btn scientific" onClick={() => scientificFunc('tan')}>tan</button>

                <button className="calc-btn scientific" onClick={() => scientificFunc('sqrt')}>√</button>
                <button className="calc-btn scientific" onClick={() => scientificFunc('log')}>log</button>
                <button className="calc-btn scientific" onClick={() => scientificFunc('ln')}>ln</button>
                <button className="calc-btn scientific" onClick={() => scientificFunc('fact')}>!</button>

                <button className="calc-btn scientific" onClick={() => scientificFunc('e')}>e</button>
                <button className="calc-btn scientific" onClick={() => scientificFunc('pi')}>π</button>
                <button className="calc-btn operator" onClick={() => performOperation('^')}>^</button>
                <button className="calc-btn equals" onClick={equals}>=</button>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default CalculatorWidget;
